CREATE TABLE disposable_notes (note_id INTEGER PRIMARY KEY, note_text TEXT); INSERT INTO disposable_notes VALUES (1, 'temporary');

DROP TABLE disposable_notes;

CREATE TABLE IF NOT EXISTS reusable_notes (note_id INTEGER PRIMARY KEY, note_text TEXT);

DROP TABLE IF EXISTS reusable_notes;

SELECT COUNT(*) AS matching_tables FROM sqlite_master WHERE type = 'table' AND name = 'reusable_notes';

